	'kdd753679' => 'I',
	'ke01e76a5' => 'We reply within one working day.',
	'ke10d6e6b' => 'A 1931 warehouse beside the canal, with the largest apartments and the only parking, €160 a month. Amara Okafor manages the house, from key handover to every monthly check-in.',
	'ke1671797' => 'e',
	'ke1e1d3d4' => 'R',
	'ke272de9e' => 'Monthly rent for a stay of thirty nights or more.',
	'ke289bae5' => 'a month, bills included',
